package com.nagriksetu.evidence;

import java.io.IOException;
import java.io.InputStream;
import java.time.Instant;
import java.util.function.Consumer;

/**
 * Stores evidence image bytes. Implementations: {@link LocalEvidenceStorageService} (persistent local
 * directory, for development and single-server deployments) and {@link S3EvidenceStorageService}
 * (AWS S3 or any S3-compatible object store).
 *
 * <p>Keys are always generated by the server (see {@link EvidenceService}); user-supplied file names are
 * never used to build a storage location.
 */
public interface EvidenceStorageService {

    /** Short provider identifier persisted with each evidence record, e.g. "local" or "s3". */
    String providerName();

    void store(String key, InputStream content, long sizeBytes, String contentType) throws IOException;

    StoredObject open(String key) throws IOException;

    boolean exists(String key);

    void delete(String key);

    /** Visits stored keys last modified before {@code cutoff}; used to clean up orphaned files. */
    void listKeysOlderThan(Instant cutoff, Consumer<String> visitor) throws IOException;

    record StoredObject(InputStream content, long sizeBytes) {
    }
}
